(function(r){'use strict';const D=r.NeonCombat.PlayerResources340,panels=new WeakMap();
function decorate(host,g){const a=host.querySelector('[data-start282]');if(!a?.href)return;try{const u=new URL(a.href),s=D.info(g);for(const[k,on]of[['playerHealth340',s.health],['playerEnergy340',s.energy]]){if(on)u.searchParams.set(k,'1');else u.searchParams.delete(k);}a.href=u.href;}catch{}}
function mount(host,g){let entry=panels.get(host);if(!entry){const box=document.createElement('details');box.open=true;box.setAttribute('data-player-resources340','');box.innerHTML='<summary>Player resources</summary><p><label><input type="checkbox" data-player-health340 aria-label="Player unlimited health"> Player unlimited health</label></p><p><label><input type="checkbox" data-player-energy340 aria-label="Player unlimited energy"> Player unlimited energy</label></p><p>Applies immediately to the active hero. Hit reactions, recovery, cooldowns and ammunition rules still apply. Options stay on through Restart and scene changes in this tab. Uncheck to return to normal depletion.</p><p data-resource-status340 role="status"></p>';entry={box,g};panels.set(host,entry);for(const[key,selector]of[['health','[data-player-health340]'],['energy','[data-player-energy340]']])box.querySelector(selector).onchange=e=>{D.set(entry.g,key,!!e.target.checked);refresh(host);};host.addEventListener?.('change',()=>decorate(host,entry.g));host.addEventListener?.('click',()=>decorate(host,entry.g));host.prepend(box);}entry.g=g;refresh(host);}
function refresh(host){const entry=panels.get(host);if(!entry)return;D.sync(entry.g);const s=D.info(entry.g);entry.box.querySelector('[data-player-health340]').checked=s.health;entry.box.querySelector('[data-player-energy340]').checked=s.energy;entry.box.querySelector('[data-resource-status340]').textContent=s.restartRequired?'Hero already defeated: restart to use unlimited health.':(s.health||s.energy?'Developer overrides active · ':'Normal resources · ')+'HP '+Math.ceil(s.hp)+' / '+s.maxHp+' · Energy '+Math.floor(s.energyCurrent)+' / '+s.maxEnergy;decorate(host,entry.g);}
r.PlayerResourcesUI340={mount,refresh};
})(globalThis);
